// 빌드 결과(dist)를 점검한다. 하나라도 실패하면 종료 코드 1.
//
//   node scripts/verify-build.mjs
//
// - 페이지마다: title, description, canonical, og:image(파일 존재), h1 하나, lang
// - 내부 링크와 #앵커가 실제 파일·id 로 이어지는지
// - target=_blank 외부 링크에 rel="noopener noreferrer"
// - img 의 alt·width·height
// - 운영 화면에 나가면 안 되는 문자열(임시값·가짜 연락처)
// - 화면 글자가 모두 글꼴 부분 집합에 들어 있는지
// - 페이지별 초기 JS(gzip) 60KB 이하
// - 인라인 실행 스크립트 없음(CSP script-src 'self')
// - SITE_ENV=production 이면 robots 가 색인을 허용하는지, 아니면 막는지
import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';
import { gzipSync } from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { Blob as HbBlob, Face as HbFace } from 'harfbuzzjs';
import { convert } from 'fontverter';

const root = fileURLToPath(new URL('..', import.meta.url));
const dist = join(root, 'dist');
const SITE = 'https://www.irumx.app';
const env = process.env.SITE_ENV === 'production' ? 'production' : 'preview';

const failures = [];
const fail = (where, msg) => failures.push(`${where}: ${msg}`);

function walk(dir, acc = []) {
  for (const n of readdirSync(dir)) {
    const p = join(dir, n);
    if (statSync(p).isDirectory()) walk(p, acc);
    else acc.push(p);
  }
  return acc;
}

const files = walk(dist);
const htmlFiles = files.filter((f) => f.endsWith('.html'));

/** 주소 → dist 파일 (Workers 정적 자산 규칙: /about → about.html, / → index.html) */
function resolvePath(pathname) {
  const clean = decodeURIComponent(pathname.replace(/\/$/, '')) || '/';
  if (clean === '/') return join(dist, 'index.html');
  const direct = join(dist, clean);
  if (existsSync(direct) && statSync(direct).isFile()) return direct;
  if (existsSync(direct + '.html')) return direct + '.html';
  if (existsSync(join(direct, 'index.html'))) return join(direct, 'index.html');
  return null;
}

const attr = (tag, name) => {
  const m = tag.match(new RegExp(`\\s${name}="([^"]*)"`));
  return m ? m[1] : null;
};
const decode = (s) =>
  s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(+n))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)));

const ids = new Map();
for (const f of htmlFiles) {
  const html = readFileSync(f, 'utf8');
  ids.set(f, new Set([...html.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1])));
}

// 글꼴에 들어 있는 글자
const fontBuf = await convert(readFileSync(join(dist, 'fonts/irumx-sans.woff2')), 'truetype');
const covered = new Set(new HbFace(new HbBlob(fontBuf), 0).collectUnicodes());

const BANNED = [
  /추후\s*입력/,
  /123-45-67890/,
  /lorem ipsum/i,
  /hello@irumx\.app/i,
  /contact@irumx\.app/i,
  /info@irumx\.app/i,
  /IRUMX\s*Inc\.?/i,
  /주식회사\s*이룸엑스/,
  /\(주\)\s*이룸엑스/,
  /\bTODO\b/,
  /\bundefined\b/,
  /\bNaN\b/,
  /\[object Object\]/,
  /전송\s*완료/,
  /100%\s*재직/,
  /완전한\s*익명/,
  /안전한\s*거래\s*보장/,
];

let jsBudgetMax = 0;
for (const f of htmlFiles) {
  const where = relative(dist, f);
  const html = readFileSync(f, 'utf8');
  const is404 = where === '404.html';

  if (!/<html lang="ko">/.test(html)) fail(where, 'lang="ko" 없음');
  // 좁은 화면에서 사라지는 <br class="br-lg"> 양옆이 모두 글자면 두 낱말이 붙어 보인다(‘이야기를시작해’)
  const glued = html.match(/[^\s>]<br class="br-lg"[^>]*>[^\s<]/);
  if (glued) fail(where, `br-lg 양옆에 띄어쓰기 없음: ${glued[0]}`);
  if (!/<title>[^<]{4,}<\/title>/.test(html)) fail(where, 'title 없음');
  const desc = html.match(/<meta name="description" content="([^"]*)"/);
  if (!desc || desc[1].length < 30) fail(where, 'description 이 없거나 너무 짧음');
  if (desc && desc[1].length > 160) fail(where, `description 이 160자를 넘음(${desc[1].length})`);
  const canon = html.match(/<link rel="canonical" href="([^"]*)"/);
  if (!canon || !canon[1].startsWith(SITE)) fail(where, 'canonical 없음');
  const og = html.match(/<meta property="og:image" content="([^"]*)"/);
  if (!og) fail(where, 'og:image 없음');
  else if (!resolvePath(new URL(og[1]).pathname)) fail(where, `og:image 파일 없음 ${og[1]}`);
  for (const p of ['og:title', 'og:description', 'og:url', 'og:type', 'og:locale', 'og:site_name']) {
    if (!html.includes(`property="${p}"`)) fail(where, `${p} 없음`);
  }
  if (!html.includes('name="twitter:card"')) fail(where, 'twitter:card 없음');
  if (!is404 && !/hreflang="ko-KR"/.test(html)) fail(where, 'hreflang 없음');
  if (/^services\/[^/]+\.html$/.test(where) && !html.includes('"FAQPage"')) fail(where, '서비스 FAQPage 구조화 데이터 없음');
  const h1s = html.match(/<h1[\s>]/g) ?? [];
  if (h1s.length !== 1) fail(where, `h1 이 ${h1s.length}개`);

  const robots = html.match(/<meta name="robots" content="([^"]*)"/)?.[1] ?? '';
  if (env === 'production' && !is404 && !robots.startsWith('index')) fail(where, 'production 인데 noindex');
  if (env !== 'production' && !robots.startsWith('noindex')) fail(where, 'preview 인데 색인 허용');
  if (is404 && !robots.startsWith('noindex')) fail(where, '404 는 noindex 여야 함');

  // 구조화 데이터는 JSON 으로 읽혀야 한다
  for (const m of html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)) {
    try {
      JSON.parse(m[1]);
    } catch {
      fail(where, 'JSON-LD 를 읽을 수 없음');
    }
  }

  // 인라인 실행 스크립트 금지
  for (const m of html.matchAll(/<script([^>]*)>([\s\S]*?)<\/script>/g)) {
    const a = m[1];
    if (/type="application\/ld\+json"/.test(a)) continue;
    if (!/\ssrc="/.test(a) && m[2].trim()) fail(where, '인라인 스크립트(CSP 에 막힘)');
  }
  if (/\son[a-z]+="/i.test(html)) fail(where, '인라인 이벤트 처리기');

  // 링크
  for (const m of html.matchAll(/<a\s[^>]*>/g)) {
    const tag = m[0];
    const href = attr(tag, 'href');
    if (href == null) continue;
    if (attr(tag, 'target') === '_blank') {
      const rel = attr(tag, 'rel') ?? '';
      if (!rel.includes('noopener') || !rel.includes('noreferrer')) fail(where, `rel 없음 ${href}`);
    }
    if (href.startsWith('mailto:') || href.startsWith('http')) continue;
    const u = new URL(decode(href), SITE + '/' + where.replace(/\.html$/, ''));
    if (u.origin !== SITE) continue;
    const target = u.pathname === '/' + where.replace(/\.html$/, '') ? f : resolvePath(u.pathname);
    if (!target) {
      fail(where, `깨진 내부 링크 ${href}`);
      continue;
    }
    if (u.hash && target.endsWith('.html') && !ids.get(target)?.has(decodeURIComponent(u.hash.slice(1))))
      fail(where, `없는 앵커 ${href}`);
  }

  // 이미지
  for (const m of html.matchAll(/<img\s[^>]*>/g)) {
    const tag = m[0];
    if (attr(tag, 'alt') == null) fail(where, 'img alt 없음');
    if (!attr(tag, 'width') || !attr(tag, 'height')) fail(where, 'img 크기 미지정(CLS)');
    const src = attr(tag, 'src');
    if (src && src.startsWith('/') && !resolvePath(src.split('?')[0])) fail(where, `이미지 파일 없음 ${src}`);
  }
  for (const m of html.matchAll(/srcset="([^"]*)"/g)) {
    for (const part of m[1].split(',')) {
      const src = part.trim().split(/\s+/)[0];
      if (src.startsWith('/') && !resolvePath(src.split('?')[0])) fail(where, `srcset 파일 없음 ${src}`);
    }
  }

  // 화면 글자
  const text = decode(
    html
      .replace(/<script[\s\S]*?<\/script>/g, ' ')
      .replace(/<style[\s\S]*?<\/style>/g, ' ')
      .replace(/<[^>]+>/g, ' '),
  );
  for (const re of BANNED) if (re.test(text)) fail(where, `금지 문자열 ${re}`);
  const missing = new Set();
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp > 0x20 && !covered.has(cp)) missing.add(ch);
  }
  if (missing.size) fail(where, `글꼴에 없는 글자: ${[...missing].join('')}`);

  // 초기 JS 용량(gzip)
  let js = 0;
  for (const m of html.matchAll(/<script[^>]*\ssrc="([^"]+)"/g)) {
    const p = resolvePath(m[1]);
    if (p) js += gzipSync(readFileSync(p)).length;
    else fail(where, `스크립트 파일 없음 ${m[1]}`);
  }
  jsBudgetMax = Math.max(jsBudgetMax, js);
  if (js > 60 * 1024) fail(where, `초기 JS ${Math.round(js / 1024)}KB > 60KB`);
}

// 가운뎃점 묶음(.nb)은 상자를 만들지 않아야 한다 — 상자가 있으면 flex 칩·버튼 안에서 gap 만큼 벌어진다(‘개 발·AI’)
{
  const dir = join(dist, '_astro');
  const css = readdirSync(dir).filter((n) => n.endsWith('.css')).map((n) => readFileSync(join(dir, n), 'utf8')).join('');
  if (!/\.nb\{[^}]*display:contents/.test(css)) fail('css', '.nb 에 display:contents 없음');
  if (/class="nb"/.test(readFileSync(join(dist, 'index.html'), 'utf8')) === false) fail('index.html', '가운뎃점 묶음 처리가 돌지 않음');
}

// robots.txt · sitemap
const robotsTxt = readFileSync(join(dist, 'robots.txt'), 'utf8');
if (env === 'production' && !/Allow: \//.test(robotsTxt)) fail('robots.txt', 'production 인데 차단');
if (env !== 'production' && !/Disallow: \/\n/.test(robotsTxt)) fail('robots.txt', 'preview 인데 허용');
const sitemap = readFileSync(join(dist, 'sitemap-0.xml'), 'utf8');
for (const p of ['/', '/about', '/services', '/services/yeopjari', '/services/yeopjari-insight', '/services/yeopjari-review', '/services/yeopjari-workkit', '/services/irum-biz', '/services/irum-beauty', '/services/irum-aicc', '/services/irum-law', '/services/irum-check', '/services/irum-agent', '/services/irum-eval', '/partnership', '/contact', '/privacy']) {
  if (!sitemap.includes(`<loc>${SITE}${p === '/' ? '/' : p}</loc>`)) fail('sitemap', `${p} 없음`);
}
if (sitemap.includes('404')) fail('sitemap', '404 포함');
if (!existsSync(join(dist, '404.html'))) fail('dist', '404.html 없음');
for (const f of ['llms.txt', 'llms-full.txt']) {
  if (!existsSync(join(dist, f)) || readFileSync(join(dist, f), 'utf8').length < 200) fail('dist', `${f} 없음`);
}
const keyFile = readdirSync(dist).find((n) => /^[0-9a-f]{32}\.txt$/.test(n));
if (!keyFile || readFileSync(join(dist, keyFile), 'utf8').trim() !== keyFile.slice(0, 32)) fail('dist', 'IndexNow 키 파일 없음');

const contactHtml = readFileSync(join(dist, 'contact.html'), 'utf8');
const mode = contactHtml.match(/data-mode="(\w+)"/)?.[1];
const warnings = [];
const privacy = readFileSync(join(dist, 'privacy.html'), 'utf8');
if (mode === 'send') {
  const sitekey = contactHtml.match(/data-sitekey="([^"]+)"/)?.[1] ?? '';
  if (env === 'production' && /^[123]x0{10,}/.test(sitekey)) fail('contact', 'production 빌드에 Turnstile 테스트 키');
  if (!/data-email="[^"@]+@[^"]+"/.test(contactHtml)) fail('contact', 'send 모드인데 받는 주소 없음');
  if (!/data-sitekey="[^"]{10,}"/.test(contactHtml)) fail('contact', 'send 모드인데 Turnstile 사이트 키 없음');
  if (!/data-action="send"/.test(contactHtml)) fail('contact', '문의 보내기 버튼 없음');
  if (!/name="consent"/.test(contactHtml)) fail('contact', '개인정보 동의 칸 없음');
  for (const must of ['보유 기간', '처리 위탁', 'Resend', '개인정보 보호책임자', '정보주체의 권리'])
    if (!privacy.includes(must)) fail('privacy', `send 모드인데 처리방침에 '${must}' 없음`);
  const headers = readFileSync(join(dist, '_headers'), 'utf8');
  if (!/\/contact\n[\s\S]*?challenges\.cloudflare\.com/.test(headers)) fail('_headers', '/contact CSP 에 Turnstile 허용 없음');
} else if (mode === 'email') {
  const email = contactHtml.match(/data-email="([^"]+)"/)?.[1];
  if (!email || !email.includes('@')) fail('contact', 'email 모드인데 주소 없음');
  if (!privacy.includes('이메일로 보낸 문의')) fail('privacy', '이메일 문의 안내 절 없음');
} else if (/data-action="(mail|send)"/.test(contactHtml)) {
  fail('contact', '연락처가 없는데 보내기 버튼이 있음');
}
for (const w of warnings) console.warn('  ! ' + w);
if (failures.length) {
  console.error(failures.map((f) => '  ✗ ' + f).join('\n'));
  process.exit(1);
}
console.log('  ✓ 모두 통과');
// @ts-check
import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import glueInterpunct from './scripts/glue-interpunct.mjs';

const SITE = 'https://www.irumx.app';

export default defineConfig({
  site: SITE,
  // 테스트에서 이메일 문의 모드 빌드를 따로 만들 때만 바꾼다(npm run test:build).
  outDir: process.env.ASTRO_OUT_DIR || './dist',
  // /about 처럼 슬래시 없는 주소를 표준으로 쓴다. Workers 정적 자산은 about.html 을 /about 으로 제공한다.
  trailingSlash: 'never',
  build: {
    format: 'file',
    inlineStylesheets: 'auto',
  },
  compressHTML: true,
  prefetch: false,
  devToolbar: { enabled: false },
  integrations: [
    sitemap({
      filter: (page) => !page.includes('/404'),
      changefreq: 'monthly',
      // lastmod 는 넣지 않는다 — 빌드 시각을 넣으면 배포마다 모든 주소가 ‘바뀜’이 되어 검색엔진이 값을 믿지 않는다
      i18n: undefined,
    }),
    // 가운뎃점(·)이 줄 첫머리에 오지 않게 — scripts/glue-interpunct.mjs
    glueInterpunct(),
  ],
  vite: {
    // 스크립트·이미지는 HTML 에 인라인하지 않는다 — CSP 가 script-src 'self' 만 허용한다(public/_headers).
    // CSS 만 기본 기준(4KB 미만)으로 인라인해 작은 컴포넌트 스타일이 따로 렌더링을 막지 않게 한다
    // (style-src 는 'unsafe-inline' 허용). 숫자 0 을 주면 Astro 도 CSS 를 하나도 인라인하지 않는다.
    build: { assetsInlineLimit: (file) => (file.endsWith('.css') ? undefined : false) },
  },
  image: {
    // 원본은 src/assets 의 PNG. 빌드 때 AVIF/WebP 여러 폭으로 만든다.
    responsiveStyles: false,
  },
});
import { expect, test } from '@playwright/test';

const PAGES = ['/', '/about', '/services', '/services/yeopjari', '/services/yeopjari-insight', '/services/yeopjari-review', '/services/yeopjari-workkit', '/services/irum-biz', '/services/irum-beauty', '/services/irum-aicc', '/services/irum-law', '/services/irum-check', '/services/irum-agent', '/services/irum-eval', '/partnership', '/contact', '/privacy'];

test.describe('페이지', () => {
  for (const path of PAGES) {
    test(`${path} — 200, 제목 하나, 가로 넘침 없음, 콘솔 오류 없음`, async ({ page }) => {
      const errors: string[] = [];
      page.on('pageerror', (e) => errors.push(String(e)));
      page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
      const res = await page.goto(path);
      expect(res?.status()).toBe(200);
      await expect(page.locator('h1')).toHaveCount(1);
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      expect(overflow).toBeLessThanOrEqual(0);
      expect(errors).toEqual([]);
    });
  }

  test('없는 주소는 404 상태와 안내 페이지', async ({ page }) => {
    const res = await page.goto('/no-such-page');
    expect(res?.status()).toBe(404);
    await expect(page.getByRole('heading', { level: 1 })).toHaveText('찾으시는 페이지가 없습니다.');
    await expect(page.locator('meta[name="robots"]')).toHaveAttribute('content', /noindex/);
  });

  test('HTML 은 Worker 가 gzip 으로 압축하고, 보안 헤더·no-transform 은 그대로 남는다', async ({ request }) => {
    for (const [path, status] of [['/', 200], ['/contact', 200], ['/__no_such_page__', 404]] as const) {
      const res = await request.get(path, { headers: { 'Accept-Encoding': 'gzip' } });
      expect(res.status()).toBe(status);
      const h = res.headers();
      expect(h['content-encoding']).toBe('gzip');
      expect(h['cache-control']).toContain('no-transform');
      expect(h['content-security-policy']).toContain("script-src 'self'");
      expect(h['x-frame-options']).toBe('DENY');
      expect(await res.text()).toContain('<h1');
    }
    // 압축본의 약한 ETag 로 다시 물으면 304
    const first = await request.get('/', { headers: { 'Accept-Encoding': 'gzip' } });
    const again = await request.get('/', { headers: { 'Accept-Encoding': 'gzip', 'If-None-Match': first.headers()['etag'] } });
    expect(again.status()).toBe(304);
  });

  test('끝 슬래시는 슬래시 없는 표준 주소로 보낸다', async ({ request }) => {
    const res = await request.get('/about/', { maxRedirects: 0 });
    expect([301, 307, 308]).toContain(res.status());
    expect(res.headers()['location']).toMatch(/\/about$/);
  });

  test('외부 링크는 새 탭 + noopener noreferrer + 새 탭 안내', async ({ page }) => {
    await page.goto('/services/yeopjari');
    const links = page.locator('a[target="_blank"]');
    const n = await links.count();
    expect(n).toBeGreaterThan(0);
    for (let i = 0; i < n; i++) {
      const a = links.nth(i);
      await expect(a).toHaveAttribute('rel', 'noopener noreferrer');
      await expect(a).toContainText('새 탭에서 열림');
    }
  });

  test('모든 내부 링크가 열린다', async ({ page, request }) => {
    const seen = new Set<string>();
    for (const path of PAGES) {
      await page.goto(path);
      const hrefs = await page.$$eval('a[href^="/"]', (as) => as.map((a) => a.getAttribute('href')!));
      hrefs.forEach((h) => seen.add(h.split('#')[0]));
