/**
 * 문의 접수 API — POST /api/inquiry
 * 수신 메일 전달 웹훅 — POST /api/resend-inbound (아래 handleInbound)
 *
 * 이 Worker 는 /api/* 와 HTML 페이지 요청을 받는다(wrangler.jsonc 의 run_worker_first — CSS·JS·글꼴·이미지 등은
 * 정적 자산이 바로 응답한다). HTML 은 정적 자산을 그대로 가져와 gzip 으로 압축만 해서 돌려준다(serveHtml).
 *
 * 순서: 출처 확인 → 크기·형식 → 속도 제한 → 미끼 칸·작성 시간 → 입력 검증(브라우저와 같은 규칙)
 *       → Turnstile 확인 → help@irumx.app 에 발송(멱등 키로 중복 발송 방지) — 계정 공용 메일 관문(sendEmail)을 거쳐
 *         Resend 한도 안이면 Resend, 넘으면 Cloudflare Email Service
 *
 * 개인정보: 문의 내용을 저장하거나 로그로 남기지 않는다. 오류 로그에는 코드만 적는다.
 * 방문자에게 확인 메일을 보내지 않는다 — 공개 양식이 임의 주소로 메일을 보내는 통로가 되지 않게.
 */
import { composeSubject, composeText, validate, type Inquiry } from '../src/lib/inquiry';
import { bytesToB64, verifySvix } from './svix';

interface RateLimit {
  limit(opts: { key: string }): Promise<{ success: boolean }>;
}

export interface Env {
  ASSETS: { fetch(req: Request): Promise<Response> };
  /** IP 하나당 */
  INQUIRY_RATE_IP?: RateLimit;
  /** 사이트 전체 */
  INQUIRY_RATE_ALL?: RateLimit;
  RESEND_API_KEY?: string;
  TURNSTILE_SECRET_KEY?: string;
  /** 받는 주소 */
  INQUIRY_TO: string;
  /** 보내는 주소(Resend 에서 인증된 irumx.app) */
  INQUIRY_FROM: string;
  /** 쉼표로 구분한 허용 출처 */
  ALLOWED_ORIGINS: string;
  /** Turnstile 응답의 hostname·action 까지 확인(운영). 테스트 키는 hostname 이 다르므로 끈다 */
  TURNSTILE_STRICT?: string;
  /** 테스트에서 Resend 대신 가짜 서버를 쓸 때만(기본 https://api.resend.com) */
  RESEND_API_BASE?: string;
  /** 받은 메일을 읽는 키(Resend full access — 받은 메일 조회에만 쓴다) */
  RESEND_READ_API_KEY?: string;
  /** Resend 웹훅 서명 비밀 값(whsec_...) */
  RESEND_WEBHOOK_SECRET?: string;
  /** 받은 메일을 전달할 주소(개인 주소라 저장소에 두지 않고 비밀 값으로) */
  FORWARD_TO?: string;
  /** 전달할 수신 주소(쉼표 구분). 없으면 INQUIRY_TO 하나 — 목록에 없는 같은 도메인 주소는 건드리지 않는다 */
  FORWARD_INBOXES?: string;
  /** 전달 메일의 보내는 주소 */
  FORWARD_FROM?: string;
  /** 계정 공용 메일 관문(서비스 바인딩 mail-gateway) — 없으면 Resend 직접 */
  MAIL?: { fetch(input: string, init?: RequestInit): Promise<Response> };
}

const resendBase = (env: Env) => (env.RESEND_API_BASE || 'https://api.resend.com').replace(/\/$/, '');

// 계정 공용 메일 관문(서비스 바인딩 MAIL): Resend 한도 안이면 Resend, 넘으면 Cloudflare Email Service.
// 요청·응답은 Resend POST /emails 그대로다. 바인딩이 없거나(로컬·시험 — RESEND_API_BASE 가짜 서버) 관문이 응답하지 않으면 Resend 직접.
function sendEmail(env: Env, init: RequestInit): Promise<Response> {
  const url = `${resendBase(env)}/emails`;
  return env.MAIL && !env.RESEND_API_BASE
    ? env.MAIL.fetch('https://mail-gateway/emails', init).catch(() => fetch(url, init))
    : fetch(url, init);
}

const MAX_BODY = 16 * 1024;
const MIN_ELAPSED_MS = 3000;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

function json(status: number, body: Record<string, unknown>, extra: Record<string, string> = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
      ...extra,
    },
  });
}

const fail = (status: number, code: string, fields?: Record<string, string>) =>
  json(status, { ok: false, code, ...(fields ? { fields } : {}) });

async function verifyTurnstile(env: Env, token: string, ip: string) {
  // idempotency_key 는 넣지 않는다 — 같은 문의를 새 토큰으로 다시 보낼 때 이전 실패 결과가 되돌아오지 않게.
  const body = new FormData();
  body.append('secret', env.TURNSTILE_SECRET_KEY ?? '');
  body.append('response', token);
  if (ip) body.append('remoteip', ip);
  const res = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { method: 'POST', body });
  if (!res.ok) return false;
  const out = (await res.json()) as { success: boolean; hostname?: string; action?: string };
  if (!out.success) return false;
  if (env.TURNSTILE_STRICT === 'true') {
    const allowedHosts = env.ALLOWED_ORIGINS.split(',').map((o) => new URL(o.trim()).hostname);
    if (!out.hostname || !allowedHosts.includes(out.hostname)) return false;
    if (out.action !== 'inquiry') return false;
  }
  return true;
}

async function handleInquiry(req: Request, env: Env): Promise<Response> {
  if (req.method !== 'POST') return fail(405, 'method', undefined);

  // 같은 사이트의 문의 페이지에서 온 요청만
  const origin = req.headers.get('Origin') ?? '';
  const allowed = env.ALLOWED_ORIGINS.split(',').map((o) => o.trim());
  if (!allowed.includes(origin)) return fail(403, 'rejected');

  if (!(req.headers.get('Content-Type') ?? '').startsWith('application/json')) return fail(415, 'invalid');
  const len = Number(req.headers.get('Content-Length') ?? '0');
  if (len > MAX_BODY) return fail(413, 'invalid');

  if (!env.RESEND_API_KEY || !env.TURNSTILE_SECRET_KEY) {
    console.error('inquiry: not configured');
    return fail(503, 'unavailable');
  }

  const ip = req.headers.get('CF-Connecting-IP') ?? '';
  if (env.INQUIRY_RATE_ALL && !(await env.INQUIRY_RATE_ALL.limit({ key: 'all' })).success)
    return fail(429, 'rate_limited');
  if (env.INQUIRY_RATE_IP && !(await env.INQUIRY_RATE_IP.limit({ key: ip || 'unknown' })).success)
    return fail(429, 'rate_limited');

  let raw: Record<string, unknown>;
  try {
    const text = await req.text();
    if (text.length > MAX_BODY) return fail(413, 'invalid');
    raw = JSON.parse(text);
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return fail(400, 'invalid');
  } catch {
    return fail(400, 'invalid');
  }

  const str = (k: string) => (typeof raw[k] === 'string' ? (raw[k] as string) : '');
  // 미끼 칸: 사람에게는 보이지 않는 칸이 채워져 있으면 자동 등록으로 본다
  if (str('website')) return fail(400, 'rejected');
  const elapsed = typeof raw.elapsedMs === 'number' ? raw.elapsedMs : 0;
  if (elapsed < MIN_ELAPSED_MS) return fail(400, 'rejected');

  const submissionId = str('submissionId');
  if (!UUID_RE.test(submissionId)) return fail(400, 'invalid');

  const inquiry: Inquiry = {
    type: str('type'),
    name: str('name'),
    company: str('company'),
    email: str('email'),
    message: str('message'),
    consent: raw.consent === true,
  };
  const errors = validate(inquiry, true);
  if (Object.keys(errors).length) return fail(400, 'invalid', errors as Record<string, string>);

  const token = str('token');
  if (!token || token.length > 2048) return fail(403, 'verification');
  let verified = false;
  try {
    verified = await verifyTurnstile(env, token, ip);
  } catch {
    verified = false;
  }
  if (!verified) return fail(403, 'verification');

  const received = new Intl.DateTimeFormat('ko-KR', {
    timeZone: 'Asia/Seoul',
    dateStyle: 'long',
    timeStyle: 'short',
  }).format(new Date());
  const text = `${composeText(inquiry)}\n접수: ${received} (KST) · 문의 번호 ${submissionId.slice(0, 8)}\n이 메일에 답장하면 문의하신 분(${inquiry.email.trim()})에게 갑니다.`;

  let res: Response;
  try {
    res = await sendEmail(env, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${env.RESEND_API_KEY}`,
        'Content-Type': 'application/json',
        // 같은 문의를 다시 보내도(재시도·중복 클릭) 메일은 한 통만 나간다(Resend·메일 관문, 24시간)
        'Idempotency-Key': `irumx-inquiry/${submissionId}`,
        'x-mail-project': 'irumx-www',
      },
      body: JSON.stringify({
        from: env.INQUIRY_FROM,
        to: [env.INQUIRY_TO],
        reply_to: inquiry.email.trim(),
        subject: composeSubject(inquiry),
        text,
        tags: [
          { name: 'source', value: 'website' },
          { name: 'type', value: inquiry.type },
        ],
      }),
    });
  } catch {
    console.error('inquiry: resend unreachable');
    return fail(502, 'send_failed');
  }
  if (!res.ok) {
    console.error(`inquiry: resend ${res.status}`);
    return fail(502, 'send_failed');
  }
  const out = (await res.json().catch(() => ({}))) as { id?: string };
  return json(200, { ok: true, id: out.id ? String(out.id).slice(0, 8) : submissionId.slice(0, 8) });
}

