// 테스트용 정적 서버 — Workers 정적 자산과 같은 규칙으로 dist 폴더를 제공한다.
//   node scripts/serve-static.mjs <dir> <port>
// /about → about.html, /about/ → 307 /about, 없는 주소 → 404.html(404)
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { join, extname, resolve } from 'node:path';

const [dir = 'dist', port = '8821'] = process.argv.slice(2);
const base = resolve(dir);
const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.png': 'image/png',
  '.webp': 'image/webp',
  '.avif': 'image/avif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.xml': 'application/xml',
  '.txt': 'text/plain; charset=utf-8',
  '.webmanifest': 'application/manifest+json',
};

async function file(p) {
  try {
    const s = await stat(p);
    return s.isFile() ? p : null;
  } catch {
    return null;
  }
}

createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  let path = decodeURIComponent(url.pathname);
  if (path.length > 1 && path.endsWith('/')) {
    res.writeHead(307, { Location: path.slice(0, -1) + url.search });
    return res.end();
  }
  const full = join(base, path);
  if (!full.startsWith(base)) {
    res.writeHead(400);
    return res.end();
  }
  const hit =
    (path === '/' && (await file(join(base, 'index.html')))) ||
    (await file(full)) ||
    (await file(full + '.html')) ||
    (await file(join(full, 'index.html')));
  if (!hit) {
    res.writeHead(404, { 'Content-Type': TYPES['.html'] });
    return res.end(await readFile(join(base, '404.html')));
  }
  res.writeHead(200, { 'Content-Type': TYPES[extname(hit)] ?? 'application/octet-stream' });
  res.end(await readFile(hit));
}).listen(+port, '127.0.0.1', () => console.log(`serving ${dir} on http://127.0.0.1:${port}`));
/**
 * 문의 한 건의 모양·검증·문장 구성. 브라우저(src/scripts/contact.ts)와 서버(worker/index.ts)가
 * 같은 파일을 쓴다 — 두 쪽 규칙이 어긋나지 않게.
 */

export const TYPE_LABELS: Record<string, string> = {
  project: '공동 서비스 개발',
  technical: 'AI·기술 협업',
  partnership: '서비스·데이터 제휴',
  advertising: '브랜드·광고 협업',
  service: '서비스 이용·도입',
  other: '기타 문의',
};

export const LIMITS = {
  name: 40,
  company: 60,
  email: 254,
  messageMin: 10,
  messageMax: 3000,
} as const;

export interface Inquiry {
  type: string;
  name: string;
  company: string;
  /** 회신받을 이메일 — 서버 발송 방식에서만 받는다 */
  email: string;
  message: string;
  /** 개인정보 수집·이용 동의 — 서버 발송 방식에서만 */
  consent: boolean;
}

export type InquiryErrors = Partial<Record<keyof Inquiry, string>>;

const EMAIL_RE = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

export function isEmail(s: string): boolean {
  return s.length <= LIMITS.email && EMAIL_RE.test(s);
}

/**
 * @param needsReply 서버 발송 방식이면 true — 회신 이메일과 동의를 함께 검사한다.
 *   이메일 앱으로 보내는 방식에서는 보낸 사람 주소를 메일 앱이 채우므로 받지 않는다.
 */
export function validate(v: Inquiry, needsReply = false): InquiryErrors {
  const e: InquiryErrors = {};
  if (!TYPE_LABELS[v.type]) e.type = '문의 유형을 골라 주세요.';
  const name = v.name.trim();
  if (!name) e.name = '이름 또는 담당자명을 적어 주세요.';
  else if (name.length > LIMITS.name) e.name = `이름은 ${LIMITS.name}자 이내로 적어 주세요.`;
  if (v.company.trim().length > LIMITS.company) e.company = `회사명은 ${LIMITS.company}자 이내로 적어 주세요.`;
  if (needsReply) {
    const email = v.email.trim();
    if (!email) e.email = '답장받을 이메일을 적어 주세요.';
    else if (!isEmail(email)) e.email = '이메일 형식을 확인해 주세요. 예: name@company.com';
  }
  const msg = v.message.trim();
  if (!msg) e.message = '문의 내용을 적어 주세요.';
  else if (msg.length < LIMITS.messageMin) e.message = `문의 내용을 ${LIMITS.messageMin}자 이상 적어 주세요.`;
  else if (msg.length > LIMITS.messageMax) e.message = `문의 내용은 ${LIMITS.messageMax.toLocaleString('ko-KR')}자 이내로 적어 주세요.`;
  if (needsReply && !v.consent) e.consent = '개인정보 수집·이용에 동의해 주세요.';
  return e;
}

/** 제목에 줄바꿈이 끼어 머리글을 바꾸지 못하게 한 줄로 만든다 */
const oneLine = (s: string) => s.replace(/[\r\n\t]+/g, ' ').trim();

export function composeSubject(v: Inquiry): string {
  const who = oneLine(v.company) || oneLine(v.name);
  return `[이룸엑스 문의] ${TYPE_LABELS[v.type] ?? '문의'} — ${who}`.slice(0, 160);
}

/** to 가 있으면 첫 줄에 받는 주소를 적는다 — 복사·저장한 내용을 어디로 보낼지 알 수 있게 */
export function composeText(v: Inquiry, to?: string): string {
  return [
    ...(to ? [`받는 곳: ${to}`, ''] : []),
    `문의 유형: ${TYPE_LABELS[v.type] ?? ''}`,
    `이름(담당자): ${oneLine(v.name)}`,
    `회사명: ${oneLine(v.company) || '적지 않음'}`,
    ...(v.email.trim() ? [`회신 이메일: ${oneLine(v.email)}`] : []),
    '',
    '문의 내용:',
    v.message.trim(),
    '',
    '—',
    '이룸엑스 웹사이트(www.irumx.app) 문의 페이지에서 작성한 내용입니다.',
  ].join('\n');
}

/** RFC 6068: 줄바꿈은 CRLF, 값은 퍼센트 인코딩 */
export function mailtoHref(to: string, subject: string, body: string): string {
  const enc = (s: string) => encodeURIComponent(s.replace(/\r?\n/g, '\r\n'));
  return `mailto:${to}?subject=${enc(subject)}&body=${enc(body)}`;
}

