interface ReceivedEmail {
  id: string;
  from: string;
  to: string[];
  subject: string | null;
  html: string | null;
  text: string | null;
  reply_to: string[];
  created_at: string;
  headers?: Record<string, string>;
}

async function handleInbound(req: Request, env: Env): Promise<Response> {
  if (req.method !== 'POST') return fail(405, 'method');
  if (!env.RESEND_WEBHOOK_SECRET || !env.RESEND_READ_API_KEY || !env.RESEND_API_KEY || !env.FORWARD_TO) {
    console.error('inbound: not configured');
    return fail(503, 'unavailable');
  }
  const body = await req.text();
  if (body.length > 256 * 1024) return fail(413, 'invalid');
  if (!(await verifySvix(env.RESEND_WEBHOOK_SECRET, req.headers, body))) return fail(401, 'rejected');

  let event: { type?: string; data?: { email_id?: string; to?: string[] } };
  try {
    event = JSON.parse(body);
  } catch {
    return fail(400, 'invalid');
  }
  // 목록에 있는 주소로 온 메일만 전달한다(같은 도메인의 다른 주소는 건드리지 않는다)
  const inboxes = (env.FORWARD_INBOXES || env.INQUIRY_TO)
    .split(',')
    .map((a) => a.trim().toLowerCase())
    .filter(Boolean);
  const to = (event.data?.to ?? []).map((a) => addressOf(a).toLowerCase());
  const inbox = to.find((a) => inboxes.includes(a));
  if (event.type !== 'email.received' || !inbox) return json(200, { ok: true, skipped: true });
  // 전달받는 주소가 전달하는 수신함 중 하나면 메일이 돌고 돈다
  if (inboxes.includes(addressOf(env.FORWARD_TO).toLowerCase())) return fail(500, 'loop');

  const emailId = String(event.data?.email_id ?? '');
  if (!/^[0-9a-f-]{36}$/.test(emailId)) return fail(400, 'invalid');

  const base = resendBase(env);
  const read = (path: string) =>
    fetch(`${base}${path}`, { headers: { Authorization: `Bearer ${env.RESEND_READ_API_KEY}` } });

  const r = await read(`/emails/receiving/${emailId}`);
  if (!r.ok) {
    console.error(`inbound: read ${r.status}`);
    return fail(502, 'send_failed');
  }
  const mail = (await r.json()) as ReceivedEmail;

