  const attachments: { filename: string; content: string; content_type?: string; content_id?: string }[] = [];
  const skipped: string[] = [];
  const la = await read(`/emails/receiving/${emailId}/attachments`);
  if (la.ok) {
    const list = ((await la.json()) as {
      data?: { filename?: string; content_type?: string; content_id?: string | null; size?: number; download_url?: string }[];
    }).data ?? [];
    let total = 0;
    for (const a of list) {
      const name = a.filename || '첨부파일';
      if (!a.download_url || total + (a.size ?? 0) > MAX_ATTACH_TOTAL) {
        skipped.push(name);
        continue;
      }
      const f = await fetch(a.download_url);
      if (!f.ok) {
        skipped.push(name);
        continue;
      }
      const bytes = new Uint8Array(await f.arrayBuffer());
      total += bytes.length;
      if (total > MAX_ATTACH_TOTAL) {
        skipped.push(name);
        continue;
      }
      attachments.push({
        filename: name,
        content: bytesToB64(bytes),
        ...(a.content_type ? { content_type: a.content_type } : {}),
        ...(a.content_id ? { content_id: a.content_id.replace(/^<|>$/g, '') } : {}),
      });
    }
  }

  const sender = mail.headers?.from || mail.from;
  const replyTo = mail.reply_to?.length ? mail.reply_to : [addressOf(mail.from)];
  const received = new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', dateStyle: 'long', timeStyle: 'short' }).format(
    new Date(mail.created_at || Date.now()),
  );
  const note = [
    `${inbox} 로 받은 메일을 전달합니다.`,
    `보낸 사람: ${sender}`,
    `받은 시각: ${received} (KST)`,
    `답장하면 ${replyTo.join(', ')} 로 갑니다.`,
    ...(skipped.length ? [`전달하지 못한 첨부: ${skipped.join(', ')} — Resend 수신함에서 확인하세요.`] : []),
  ];
  const text = `${note.join('\n')}\n${'─'.repeat(24)}\n\n${mail.text ?? '(본문이 HTML 로만 되어 있습니다)'}`;
  const html = mail.html
    ? `<div style="font:13px/1.6 sans-serif;color:#626761;border-bottom:1px solid #dddcd4;padding:0 0 10px;margin:0 0 16px">${note
        .map(escapeHtml)
        .join('<br>')}</div>${mail.html}`
    : undefined;

  const send = await sendEmail(env, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${env.RESEND_API_KEY}`,
      'Content-Type': 'application/json',
      'Idempotency-Key': `irumx-forward/${emailId}`,
      'x-mail-project': 'irumx-www',
    },
    body: JSON.stringify({
      from: env.FORWARD_FROM || env.INQUIRY_FROM,
      to: [env.FORWARD_TO],
      reply_to: replyTo,
      subject: mail.subject || '(제목 없음)',
      text,
      ...(html ? { html } : {}),
      ...(attachments.length ? { attachments } : {}),
      tags: [{ name: 'source', value: 'forward' }],
    }),
  });
  if (!send.ok) {
    console.error(`inbound: forward ${send.status}`);
    return fail(502, 'send_failed');
  }
  return json(200, { ok: true });
}

/**
 * HTML 을 gzip 으로 압축해 돌려준다.
 *
 * HTML 에는 Cache-Control: no-transform 을 붙인다(public/_headers) — 빼면 Cloudflare 가 Bot Fight Mode 의
 * JavaScript 감지·분석 비콘 스크립트를 끼워 넣고 CSP 가 막아 콘솔 오류가 난다. 그런데 no-transform 이면
 * 엣지가 압축도 하지 않아 HTML 이 47KB 그대로 나간다. 그래서 여기서 직접 압축한다(엣지는 이미 압축된 본문을
 * 건드리지 않는다). JavaScript 감지는 영역 전체 설정이라 끄지 않는다 — 이룸뷰티(cosmetics)가 쓰고 있다.
 */
async function serveHtml(req: Request, env: Env): Promise<Response> {
  // 압축본에는 약한 ETag 를 붙여 보내므로, 되돌아온 If-None-Match 의 W/ 를 떼어 자산 쪽 304 비교가 맞게 한다
  let assetReq = req;
  const inm = req.headers.get('if-none-match');
  if (inm?.startsWith('W/')) {
    const h = new Headers(req.headers);
    h.set('if-none-match', inm.slice(2));
    assetReq = new Request(req, { headers: h });
  }
  const res = await env.ASSETS.fetch(assetReq);
  const type = res.headers.get('content-type') ?? '';
  const accepts = /\bgzip\b/i.test(req.headers.get('accept-encoding') ?? '');
  if (req.method !== 'GET' || !res.body || !type.startsWith('text/html') || !accepts || res.headers.has('content-encoding')) {
    return res;
  }
  const headers = new Headers(res.headers);
  headers.set('content-encoding', 'gzip');
  headers.delete('content-length');
  headers.append('vary', 'Accept-Encoding');
  const etag = headers.get('etag');
  if (etag && !etag.startsWith('W/')) headers.set('etag', `W/${etag}`);
  // encodeBody: 'manual' — 본문이 이미 압축되었음을 런타임에 알린다(다시 압축하지 않음)
  const init = { status: res.status, statusText: res.statusText, headers, encodeBody: 'manual' } as ResponseInit;
  return new Response(res.body.pipeThrough(new CompressionStream('gzip')), init);
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
/**
 * 문의 접수 API — POST /api/inquiry
 * 수신 메일 전달 웹훅 — POST /api/resend-inbound (아래 handleInbound)
