  await request.delete(MOCK);
  const emailId = randomUUID();
  const body = event(['help@irumx.app'], emailId);
  const res = await request.post('/api/resend-inbound', { data: body, headers: signed(body) });
  expect(res.status()).toBe(200);
  expect(await res.json()).toEqual({ ok: true });

  const sent = await mails(request);
  expect(sent).toHaveLength(1);
  const m = sent[0];
  expect(m.body.to).toEqual(['owner@example.com']);
  expect(m.body.from).toBe('이룸엑스 문의함 <website@irumx.app>');
  // 답장은 원래 문의한 사람에게
  expect(m.body.reply_to).toEqual(['visitor@example.com']);
  expect(m.body.subject).toBe('[이룸엑스 문의] AI·기술 협업 — 테스트 회사');
  expect(m.body.text).toContain('help@irumx.app 로 받은 메일을 전달합니다.');
  expect(m.body.text).toContain('사내 문서 검색 자동화 문의 본문');
  expect(m.body.html).toContain('<b>본문</b>');
  expect(m.body.attachments?.map((a) => a.filename)).toEqual(['요구사항.txt']);
  expect(Buffer.from(m.body.attachments![0].content, 'base64').toString('utf8')).toBe('첨부 파일 내용');
  expect(m.headers['idempotency-key']).toBe(`irumx-forward/${emailId}`);
  expect(m.headers['authorization']).toBe('Bearer re_test_only');
});

test('서명이 틀리거나 오래되면 401, 아무것도 보내지 않는다', async ({ request }) => {
  await request.delete(MOCK);
  const body = event(['help@irumx.app']);
  const bad = await request.post('/api/resend-inbound', { data: body, headers: signed(body, { secret: Buffer.from('wrong') }) });
  expect(bad.status()).toBe(401);
  const old = await request.post('/api/resend-inbound', {
    data: body,
    headers: signed(body, { ts: Math.floor(Date.now() / 1000) - 3600 }),
  });
  expect(old.status()).toBe(401);
  const none = await request.post('/api/resend-inbound', { data: body, headers: { 'Content-Type': 'application/json' } });
  expect(none.status()).toBe(401);
  // 서명은 맞지만 본문이 바뀐 경우
  const tampered = await request.post('/api/resend-inbound', {
    data: event(['help@irumx.app']),
    headers: signed(body),
  });
  expect(tampered.status()).toBe(401);
  expect(await mails(request)).toHaveLength(0);
});

