export function josa(word: string, a: string, b: string) {
  const ch = word.trim().slice(-1);
  const code = ch.charCodeAt(0) - 0xac00;
  if (code >= 0 && code <= 11171) return `${word}${code % 28 ? a : b}`;
  if (/[lmnr]/i.test(ch) || /[013678]/.test(ch)) return `${word}${a}`;
  return `${word}${b}`;
}

/** 서비스마다의 자주 묻는 질문 — 공개 화면에서 확인한 사실만으로 만든다. 화면과 FAQPage 구조화 데이터가 함께 쓴다 */
export function serviceFaq(s: Service) {
  return [
    { q: `${josa(s.name, '은', '는')} 어떤 서비스인가요?`, a: `${s.summary} ${s.description}` },
    { q: '누구를 위한 서비스인가요?', a: `${josa(s.audience, '을', '를')} 위한 서비스입니다.` },
    { q: '지금 이용할 수 있나요?', a: s.availability },
    ...(s.pricing ? [{ q: '비용은 어떻게 되나요?', a: s.pricing }] : []),
    {
      q: '누가 운영하나요?',
      a: `이룸엑스(IRUMX)가 직접 기획·개발·운영합니다. 이룸엑스는 대표 장형국이 운영하는 개인사업자이며, ${s.name} 주소는 ${s.host}입니다.`,
    },
  ];
}

/** 공개 서비스만, 공개 기능만. 순서가 곧 화면 순서다(첫 번째가 메인의 대표 쇼케이스). */
export const PUBLISHED_SERVICES: PublishedService[] = SERVICES.filter((s) => s.published).map((s) => ({
  ...s,
  features: s.features.filter((f) => f.published),
}));

/** 묶음별로 나눈 공개 서비스 — 빈 묶음은 뺀다. 묶음 안의 순서는 SERVICES 순서를 따른다 */
export function servicesByFamily(list: PublishedService[] = PUBLISHED_SERVICES) {
  return FAMILIES.map((f) => ({ ...f, services: list.filter((s) => s.family === f.id) })).filter(
    (g) => g.services.length > 0,
  );
}
