export const PUBLISHED_SERVICES: PublishedService[] = SERVICES.filter((s) => s.published).map((s) => ({
  ...s,
  features: s.features.filter((f) => f.published),
}));

/** 묶음별로 나눈 공개 서비스 — 빈 묶음은 뺀다. 묶음 안의 순서는 SERVICES 순서를 따른다 */
export function servicesByFamily(list: PublishedService[] = PUBLISHED_SERVICES) {
  return FAMILIES.map((f) => ({ ...f, services: list.filter((s) => s.family === f.id) })).filter(
    (g) => g.services.length > 0,
  );
}
